     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    private const int DailyLimit = 200;
     6	    private const int FeeThreshold = 100;
     7	    private const int WithdrawalFee = 5;
     8	    private const int CassetteCapacity = 5;
     9	    private const int MaxNotesPerPass = 4;
    10	
    11	    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    14	    {
    15	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    16	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    17	        null => throw new ArgumentNullException(nameof(operation)),
    18	        _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
    19	    };
    20	
    21	    private AtmResult Withdraw(AccountState account, int amount)
    22	    {
    23	        if (amount <= 0 || amount % 10 != 0)
    24	        {
    25	            return Refuse(AtmStatus.InvalidAmount, account);
    26	        }
    27	
    28	        if (account.WithdrawnToday + amount > DailyLimit)
    29	        {
    30	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    31	        }
    32	
    33	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    34	        if (amount + fee > account.Balance)
    35	        {
    36	            return Refuse(AtmStatus.InsufficientFunds, account);
    37	        }
    38	
    39	        if (FewestNotes(amount, Available()) is not { } combination)
    40	        {
    41	            return Refuse(AtmStatus.CannotDispense, account);
    42	        }
    43	
    44	        var dispensed = NoteCounts.None;
    45	        foreach (var pass in Passes(combination))
    46	        {
    47	            if (!_dispenser.Dispense(pass))
    48	            {
    49	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    50	            }
    51	
    52	            dispensed += pass;
    53	        }
    54	
    55	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    56	
    57	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    58	    }
    59	
    60	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    61	    {
    62	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
    63	        {
    64	            return Refuse(AtmStatus.InvalidAmount, account);
    65	        }
    66	
    67	        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    68	        {
    69	            return Refuse(AtmStatus.CassetteJammed, account);
    70	        }
    71	
    72	        var after = _dispenser.Stock + notes;
    73	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    74	        {
    75	            return Refuse(AtmStatus.CassetteFull, account);
    76	        }
    77	
    78	        if (!_dispenser.Load(notes))
    79	        {
    80	            return Refuse(AtmStatus.DispenserFault, account);
    81	        }
    82	
    83	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    84	    }
    85	
    86	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    87	        new(status, NoteCounts.None, 0, account);
    88	
    89	    /// <summary>Le stock, sans la cassette bloquée, qui compte pour zéro.</summary>
    90	    private NoteCounts Available()
    91	    {
    92	        var stock = _dispenser.Stock;
    93	        var jammed = _dispenser.Jammed;
    94	
    95	        return new NoteCounts(
    96	            jammed == Denomination.Fifty ? 0 : Math.Max(0, stock.Fifties),
    97	            jammed == Denomination.Twenty ? 0 : Math.Max(0, stock.Twenties),
    98	            jammed == Denomination.Ten ? 0 : Math.Max(0, stock.Tens));
    99	    }
   100	
   101	    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou null.</summary>
   102	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   103	    {
   104	        NoteCounts? best = null;
   105	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   106	        {
   107	            var afterFifties = amount - fifties * 50;
   108	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   109	            {
   110	                var rest = afterFifties - twenties * 20;
   111	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   112	                {
   113	                    continue;
   114	                }
   115	
   116	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   117	                if (best is not { } current || candidate.Total < current.Total)
   118	                {
   119	                    best = candidate;
   120	                }
   121	            }
   122	        }
   123	
   124	        return best;
   125	    }
   126	
   127	    /// <summary>Découpe la combinaison en passages d'au plus 4 billets.</summary>
   128	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   129	    {
   130	        var remaining = notes;
   131	        while (remaining.Total > 0)
   132	        {
   133	            var room = MaxNotesPerPass;
   134	            var fifties = Math.Min(room, remaining.Fifties);
   135	            room -= fifties;
   136	            var twenties = Math.Min(room, remaining.Twenties);
   137	            room -= twenties;
   138	            var tens = Math.Min(room, remaining.Tens);
   139	
   140	            var pass = new NoteCounts(fifties, twenties, tens);
   141	            remaining -= pass;
   142	
   143	            yield return pass;
   144	        }
   145	    }
   146	}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}

