        Assert.Equal(AtmStatus.InvalidAmount, Withdraw(5, new(0, 200), Of(0, 0, 0)).Status);
    }

    [Fact]
    public void DailyLimit_IsCheckedBeforeFunds()
    {
        Assert.Equal(AtmStatus.DailyLimitExceeded, Withdraw(60, new(0, 150), Full).Status);
    }

    [Fact]
